#!/bin/sh
# Regenerates src/glass.metal from the WGSL glass shader (cargo install naga-cli), then fixes the bindings:
# Params = buffer(0), backdrop = texture(0), samp = sampler(0). The blit shader lives in glass_blit.metal.
set -e
cd "$(dirname "$0")"
naga ../gpui-pre-wgpu/src/glass.wgsl /tmp/glass-naga.metal
{
  echo "// GENERATED by regen-glass.sh from vendor/gpui-pre-wgpu/src/glass.wgsl (+ glass_blit.metal). Do not edit."
  sed -e '1d' \
      -e 's/constant Params& P \[\[user(fake0)\]\]/constant Params\& P [[buffer(0)]]/' \
      -e 's/backdrop \[\[user(fake0)\]\]/backdrop [[texture(0)]]/' \
      -e 's/samp \[\[user(fake0)\]\]/samp [[sampler(0)]]/' /tmp/glass-naga.metal
  cat src/glass_blit.metal
} > src/glass.metal
! grep -q fake0 src/glass.metal
